const request = $('When Executed by Another Workflow').first().json; const data = $input.first().json; const fallbackImage = 'https://raw.githubusercontent.com/tha0rbej/hanoixanh/main/anh-chien-dich-kenh-muong.png'; const fold = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); const text = (result) => [result.title, result.content, result.url].join(' '); const mentionsHanoi = (result) => /\b(?:ha noi|hanoi)\b/.test(fold(text(result))); const mentionsPollution = (result) => /(?:o nhiem|rac|nuoc thai|bai rac|chat thai|song day|song to lich|kenh muong|diem den|beo tay|tac dong chay)/.test(fold([result.title, result.content].join(' '))); const isHttps = value => /^https:\/\/\S+$/i.test(String(value || '').trim()); const searchImages = (Array.isArray(data.images) ? data.images : []).slice(0, 3).map(img => ({ url: typeof img === 'string' ? img : img.url, caption: 'Ảnh từ kết quả tìm kiếm — chưa xác minh nguồn/quyền' + (typeof img !== 'string' && img.description ? ' (' + String(img.description).slice(0, 200) + ')' : ''), source_url: null, license_status: 'unknown' })).filter(img => isHttps(img.url)); const pool = searchImages.length ? searchImages : [{ url: fallbackImage, caption: 'Ảnh chiến dịch Hà Nội Xanh', source_url: fallbackImage, license_status: 'project_asset' }]; const compact = (value) => String(value || '').replace(/\s+/g, ' ').replace(/\.{3,}/g, ' ').replace(/\[\.\.\.\]/g, ' ').replace(/\s+/g, ' ').trim(); const sentences = (value) => compact(value).split(/(?<=[.!?。！？])\s+/).map(item => item.trim()).filter(item => item.length >= 12); const scoreStatus = (value) => { const s = fold(value); let score = 0; if (/o nhiem\s+(nang|nghiem trong|tram trong)/.test(s)) score += 8; if (/(o nhiem|rac thai|nuoc thai|beo tay|tac dong chay|rac ton dong)/.test(s)) score += 4; if (/(giai quyet|du an|dau tu|ty dong|cong suat|khoi cong|ha tang|nha may|tuyen cong|tram bom)/.test(s)) score -= 3; if (value.length > 220) score -= 4; return score; }; const conciseStatus = (result) => { const parts = [...sentences(result.title), ...sentences(result.content)]; const picked = parts.filter(item => scoreStatus(item) > 0).sort((a, b) => scoreStatus(b) - scoreStatus(a) || a.length - b.length)[0] || parts[0] || 'Chưa có mô tả hiện trạng đủ rõ.'; const severe = picked.match(/(.+?)\s+o nhiem\s+(nang|nghiem trong|tram trong)/i); if (severe && severe[1].length <= 120) { const subject = severe[1].replace(/^toan canh\s+/i, '').replace(/^vov\.vn\s*[-:：]?\s*/i, '').trim(); return (subject.charAt(0).toUpperCase() + subject.slice(1) + ' đang ô nhiễm ' + severe[2] + '.').replace(/\s+/g, ' '); } const focused = picked.replace(/^vov\.vn\s*[-:：]?\s*/i, '').replace(/^toàn cảnh\s+/i, '').replace(/\s+(sắp được giải cứu|đang được giải cứu|được giải cứu)\b.*$/i, '').trim(); const short = focused.length > 180 ? focused.slice(0, 177).replace(/\s+\S*$/, '') + '…' : focused; return /[.!?]$/.test(short) ? short : short + '.'; }; const candidates = (Array.isArray(data.results) ? data.results : []).filter(result => Number(result.score || 0) >= 0.1 && mentionsHanoi(result) && mentionsPollution(result)).slice(0, 3); const rows = candidates.map(result => ({ json: { thread_id: request.thread_id, location_name: result.title || 'Địa điểm cần xác minh', district: null, address: null, pollution_type: 'chưa phân loại', summary: conciseStatus(result), observed_at: result.published_date || null, confidence: result.published_date && result.score >= 0.6 ? 'high' : result.published_date && result.score >= 0.3 ? 'medium' : 'low', sources: [{ title: result.title, url: result.url, published_at: result.published_date || null }], images: pool } }));
if (!rows.length) return [{ json: { no_results: true } }];
return rows;

const rows = $input.all().map(item => item.json).filter(row => row.id);
if (!rows.length) return [{ json: { status: 'no_results', findings: [], message: 'Không tìm thấy nguồn phù hợp. Thử từ khóa khác hoặc mở rộng khoảng thời gian.' } }];
return [{ json: { status: 'ok', findings: rows.map(row => ({ ...row, finding_id: row.id })) } }];
